// binarySearchForMaximumConnectionCstablishmentRate(c,r)関数は、
// c個のコネクションを使用して、[0, r]の区間で最大コネクション確立
// レートの二分探索を実行します。

// これは、コネクション追跡テーブル容量のおおよその桁を見つける
// ための指数探索です
// 変数：
//   C0とR0は、それぞれコネクション追跡テーブルの大きさと
//     コネクション確立レートの安全な開始値です
//   CSとRSは、現在使用しているそれらの安全な値です
//   CTとRTは、現在調べているそれらの値です
//   betaは、Rの許容できない低下を表す係数です（たとえば、
//     beta=0.1）
//   maxrateは、媒体の最大フレームレートです
R0=binarySearchForMaximumConnectionCstablishmentRate(C0,maxrate);
for ( CS=C0, RS=R0; 1; CS=CT, RS=RT )
{
  CT=2*CS;
  RT=binarySearchForMaximumConnectionCstablishmentRate(CT,RS);
  if ( DUT_collapsed || RT < RS*beta )
    break;
}
// この時点で、コネクション追跡テーブルの大きさはCSとCTの間に
// あります。

// これは、誤差Eの範囲内でコネクション追跡テーブル容量を見つける
// ための最後の二分探索です
// 変数：
//   CSとRSは、それぞれコネクション追跡テーブルの大きさと
//     コネクション確立レートの安全な値です
//   CとRは、現在調べている値です
//   gammaは、Rの許容できない低下を表す係数です
//     （たとえば、gamma=0.5）
for ( D=CT-CS;  D>E; D=CT-CS )
{
  C=(CS+CT)/2;
  R=binarySearchForMaximumConnectionCstablishmentRate(C,RS);
  if ( DUT_collapsed || R < RS*gamma )
    CT=C; // 区間の下半分を選択する
  else
    CS=C,RS=R; // 区間の上半分を選択する
}
// この時点で、コネクション追跡テーブルの大きさは誤差Eの範囲内で
// CSです。
